while jobs:
    for job_id in list(jobs):
        result = subprocess.run(
            ['python', 'jobq.py', 'status', job_id],
            cwd='/tmp/claude-0/-home-user-token-marxing/a913bb7b-d869-598c-b2e2-5bf6438d4f34/scratchpad/ws/long-delegate-s1',
