            print(f"\n{job_id}: {status_output.strip()}")
            jobs.remove(job_id)
        else:
            state = 'UNKNOWN'
            for line in status_output.split('\n'):
                if job_id in line:
                    parts = line.split()
                    if len(parts) > 2:
                        state = parts[2]
                        break
